-- 099_bootstrap_tenant_domain_tables.sql
-- Phase 3A Part 2: create the canonical tenant-local domain tables that are
-- FK-referenced by the 101-123 tenant chain AND by extracted module
-- migrations (modules/*/source/backend/*/migrations/*).
--
-- Background:
--   tenant/101_incidents_ops_additions.sql was ported from the monolith
--   where incidents / risks / teams / vulnerabilities / findings /
--   ai_model_registry lived in the tenant schema. The port did not carry
--   their CREATE TABLE statements. Every subsequent migration that
--   references them therefore fails validate:migrations on a fresh tenant
--   schema.
--
--   The canonical shapes in two different worlds disagree on PK column
--   name:
--     - tenant chain 101-123 FKs to incidents(incident_id), risks(risk_id),
--       teams(team_id), vulnerabilities(vulnerability_id),
--       findings(finding_id), ai_model_registry(model_version_id).
--     - modules/* FKs to incidents(id), risks(id), ai_model_registry(id).
--
--   Providing both columns as UNIQUE on each bootstrap table lets either
--   FK target resolve. PK stays `id` (matches the module canonical shape);
--   the domain-specific *_id is a UNIQUE alias defaulting to a fresh UUID
--   (or substring-of-uuid for risk_id's TEXT/16-char width) so callers
--   that only populate one column still satisfy the UNIQUE constraint on
--   the other.
--
-- Idempotent: every CREATE uses IF NOT EXISTS; every ALTER uses ADD COLUMN
-- IF NOT EXISTS. Safe to re-run. On production tenants that already ran an
-- older bootstrap with only *_id as PK, the ADD COLUMN IF NOT EXISTS
-- brings `id` online without touching existing rows.
-- Runs in per-tenant schema; run-tenant-migrations.sh:155 sets search_path.
-- Alphabetic ordering 099_ < 100_ < 101_ guarantees this lands before 101.
-- ============================================================================

-- ── incidents — FK target for 101, 102, 105, 107, 116, 117, 118 + modules ──
CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.incidents (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  incident_id   UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
  tenant_id     UUID,
  title         TEXT,
  description   TEXT,
  severity      VARCHAR(30),
  status        VARCHAR(30) DEFAULT 'open',
  reported_by   VARCHAR(64),
  assigned_to   VARCHAR(64),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  deleted_at    TIMESTAMPTZ
);

ALTER TABLE __TENANT_SCHEMA__.incidents ADD COLUMN IF NOT EXISTS id UUID DEFAULT gen_random_uuid();

ALTER TABLE __TENANT_SCHEMA__.incidents ADD COLUMN IF NOT EXISTS incident_id UUID DEFAULT gen_random_uuid();

CREATE INDEX IF NOT EXISTS idx_incidents_tenant_bootstrap ON __TENANT_SCHEMA__.incidents (tenant_id);

-- ── findings — FK target for audit + related series + modules ────────────
CREATE TABLE IF NOT EXISTS findings (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  finding_id    UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
  tenant_id     UUID,
  title         TEXT,
  severity      VARCHAR(30),
  status        VARCHAR(30) DEFAULT 'open',
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE findings ADD COLUMN IF NOT EXISTS id UUID DEFAULT gen_random_uuid();

ALTER TABLE findings ADD COLUMN IF NOT EXISTS finding_id UUID DEFAULT gen_random_uuid();

CREATE INDEX IF NOT EXISTS idx_findings_tenant_bootstrap ON findings (tenant_id);
